# Grounded tests for Wigner.wignerd / wignerd_halfpi / wignerD_fixed (reduced Wigner-d).
#
# Grounding sources:
#  (1) Mathematica WignerD oracle fixture wignerD_reference.csv (287 rows of l,m,mp,reim at the
#      fixed Euler angles (π,π/2,π/2)), COPIED verbatim from
#      packages/Punctures/test/wignerD_reference.csv (generated by Punctures oracle/gen_wignerD.wl).
#      This directly grounds wignerD_fixed.
#  (2) Analytic reduced-d identities for the general-β form:
#        - wignerd(T,j,m1,m2,π/2) == wignerd_halfpi  (the β=π/2 collapse is a special case)
#        - d^j_{m,m'}(0) = δ_{m,m'}
#        - d^j_{m,m'}(β) = (-1)^(m-m') d^j_{m',m}(β)
#        - d^j_{m,m'}(β) = d^j_{-m',-m}(β)
#        - stretched value d^j_{j,j}(β) = cos(β/2)^{2j}

using Wigner, Test

const WREF = joinpath(@__DIR__, "wignerD_reference.csv")
_parse_complex(s) = (a = split(s, '|'); complex(parse(Float64, a[1]), parse(Float64, a[2])))

@testset "wignerD_fixed vs Mathematica WignerD oracle (all rows)" begin
    n = 0
    for (k, line) in enumerate(eachline(WREF))
        k == 1 && continue
        isempty(strip(line)) && continue
        f = split(line, ',')
        l = parse(Int, f[1]); m = parse(Int, f[2]); mp = parse(Int, f[3])
        ex = _parse_complex(f[4])
        got = wignerD_fixed(Float64, l, m, mp)
        @test isapprox(got, ex; atol=1e-12)
        n += 1
    end
    @test n > 250
end

@testset "wignerD_fixed BigFloat precision" begin
    setprecision(BigFloat, 192) do
        g = wignerD_fixed(BigFloat, 5, 3, 2)
        gF = wignerD_fixed(Float64, 5, 3, 2)
        @test g isa Complex{BigFloat}
        @test isapprox(Float64(real(g)), real(gF); atol=1e-12)
        @test isapprox(Float64(imag(g)), imag(gF); atol=1e-12)
    end
end

@testset "wignerd general-β == wignerd_halfpi at β=π/2" begin
    for j in 0:6, m1 in -j:j, m2 in -j:j
        @test wignerd(Float64, j, m1, m2, pi / 2) ≈ wignerd_halfpi(Float64, j, m1, m2) atol=1e-11
    end
end

@testset "wignerd identity: d^j(0) = δ" begin
    for j in 0:5, m1 in -j:j, m2 in -j:j
        expected = (m1 == m2) ? 1.0 : 0.0
        @test wignerd(Float64, j, m1, m2, 0.0) ≈ expected atol=1e-12
    end
end

@testset "wignerd identity: transpose (-1)^(m-m') symmetry" begin
    βs = [0.3, 0.9, 1.7, 2.5]
    for β in βs, j in 0:5, m1 in -j:j, m2 in -j:j
        s = iseven(m1 - m2) ? 1.0 : -1.0
        @test wignerd(Float64, j, m1, m2, β) ≈ s * wignerd(Float64, j, m2, m1, β) atol=1e-12
    end
end

@testset "wignerd identity: d^j_{m,m'} = d^j_{-m',-m}" begin
    βs = [0.3, 0.9, 1.7, 2.5]
    for β in βs, j in 0:5, m1 in -j:j, m2 in -j:j
        @test wignerd(Float64, j, m1, m2, β) ≈ wignerd(Float64, j, -m2, -m1, β) atol=1e-12
    end
end

@testset "wignerd identity: stretched d^j_{j,j}(β) = cos(β/2)^{2j}" begin
    βs = [0.3, 0.9, 1.7, 2.5, pi / 2]
    for β in βs, j in 0:6
        @test wignerd(Float64, j, j, j, β) ≈ cos(β / 2)^(2j) atol=1e-12
    end
end

@testset "wignerd_halfpi stretched value 2^{-j} (d^j_{j,j}(π/2))" begin
    for j in 0:8
        @test wignerd_halfpi(Float64, j, j, j) ≈ (1 / sqrt(2))^(2j) atol=1e-13
    end
end

@testset "wignerd BigFloat precision inherited" begin
    setprecision(BigFloat, 256) do
        g = wignerd(BigFloat, 4, 2, 1, big(pi) / 2)
        @test g isa BigFloat
        gh = wignerd_halfpi(BigFloat, 4, 2, 1)
        @test g ≈ gh rtol=1e-50
    end
end
